window.RECIPES=[{"id": "copilot-readiness-checklist", "category": "Copilot rollout & governance", "title": "Run a Microsoft Copilot readiness check before you assign licenses", "problem": "Teams buy Copilot licenses and assign them before prerequisites (apps, update channel, identity, data access) are in place, leading to a poor first impression.", "steps": ["Confirm users have a qualifying Microsoft 365 base license (Copilot isn't available with device-based licensing for Microsoft 365 Apps) and Microsoft 365 Apps on Current Channel or Monthly Enterprise Channel.", "Confirm users have a Microsoft Entra ID account, an Exchange Online mailbox (for mail/calendar/meeting grounding) and OneDrive (needed for some features).", "Network: allow the whole *.cloud.microsoft domain (including copilot.cloud.microsoft) and full WebSocket Secure (WSS) connectivity to *.office.com and *.cloud.microsoft; avoid TLS inspection on that traffic.", "Review oversharing risk in SharePoint before broad rollout (see the oversharing recipes).", "Assign licenses to a pilot group first and validate users with the Copilot License Details diagnostic."], "v": "2026-10-30", "n": 3, "tg": ["Copilot", "Licensing"], "c": "2026-10-12"}, {"id": "copilot-pilot-group-licensing", "category": "Copilot rollout & governance", "title": "Assign Copilot licenses to a pilot group with group-based licensing", "problem": "Manually assigning Copilot licenses per user does not scale and is hard to audit.", "steps": ["Create a security group, e.g. 'SG-Copilot-Pilot' (no nested groups — they aren't supported).", "Microsoft 365 admin center > Billing > Licenses > Assign licenses: pick the group and the Microsoft Copilot subscription (group-based licensing is managed in the Microsoft 365 admin center, not the Entra admin center).", "Add pilot users to the group; licenses are applied automatically.", "Monitor errors under Billing > Licenses > the product > Errors & issues."], "v": "2026-10-30", "n": 2, "tg": ["Copilot", "Licensing"], "c": "2026-10-12"}, {"id": "copilot-assign-license-graph", "category": "Copilot rollout & governance", "title": "Assign a Microsoft Copilot license to a user with Microsoft Graph PowerShell", "problem": "You need to script license assignment for a list of users.", "steps": ["Connect: `Connect-MgGraph -Scopes 'User.ReadWrite.All','Organization.Read.All'`", "Find the SKU: `Get-MgSubscribedSku | Select SkuPartNumber, SkuId`", "Set a usage location if missing: `Update-MgUser -UserId user@contoso.com -UsageLocation SE`", "Assign: `Set-MgUserLicense -UserId user@contoso.com -AddLicenses @{SkuId='<SkuId>'} -RemoveLicenses @()`"], "v": "2026-10-30", "n": 2, "tg": ["Copilot", "Licensing", "PowerShell & Graph"], "c": "2026-10-12"}, {"id": "copilot-adoption-hub", "category": "Copilot rollout & governance", "title": "Plan adoption with the Microsoft Copilot adoption resources", "problem": "Licenses get assigned but usage stays low because nobody planned training or champions.", "steps": ["Pick 3–5 business scenarios per department (meeting recap, email drafting, document summary).", "Recruit a champions group and give them early access.", "Use the Copilot Dashboard in Viva Insights to track readiness, adoption and impact (no paid Viva Insights license needed).", "Run monthly 'show and tell' sessions and collect prompts that work."], "v": "2026-10-30", "n": 2, "tg": ["Copilot"], "c": "2026-10-12"}, {"id": "copilot-web-grounding-control", "category": "Copilot rollout & governance", "title": "Decide whether Copilot can use web content (web search)", "problem": "Security asks whether prompts can be sent to Bing for web grounding and wants a control.", "steps": ["Review how web search works: Copilot sends short generated search queries to Bing — not the full prompt, files or Entra identity (very short prompts can be sent as-is).", "Control it with the 'Allow web search in Copilot' policy in Cloud Policy service for Microsoft 365: enabled, disabled, or disabled in Work mode but enabled in Web mode and Copilot Chat.", "For finer control, a Purview DLP rule can block web search only when prompts contain sensitive information types.", "Document the decision and communicate it to users."], "v": "2026-10-30", "n": 2, "tg": ["Copilot"], "c": "2026-10-12"}, {"id": "copilot-teams-meeting-transcription", "category": "Copilot rollout & governance", "title": "Make Copilot in Teams meetings work: transcription and recording policies", "problem": "Users can't use Copilot in meetings, or Copilot disappears after the meeting.", "steps": ["Transcription must be allowed (Teams meeting policy, -AllowTranscription) and a transcript started for Copilot to work after the meeting.", "Organizers choose 'During and after the meeting', 'Only during the meeting' or 'Off' in meeting options.", "Teams admin center > Meetings > Meeting policies > Recording & transcription > Copilot: On, On with saved transcript required (default), On with transcript saved by default, or Off.", "PowerShell: `Set-CsTeamsMeetingPolicy -Identity <policy> -Copilot EnabledWithTranscriptDefaultOn`"], "v": "2026-10-30", "n": 3, "tg": ["Copilot", "PowerShell & Graph"], "c": "2026-10-12"}, {"id": "ca-require-mfa-copilot", "category": "Conditional Access for AI", "title": "Require phishing-resistant MFA for users accessing Microsoft Copilot", "problem": "Copilot can surface a lot of data quickly, so a compromised account is more dangerous. You want stronger authentication for licensed users.", "steps": ["Entra admin center > Entra ID > Conditional Access > Policies > New policy.", "Users: include the Copilot license group; exclude break-glass accounts.", "Target resources: Office 365 (the Office 365 app group includes Enterprise Copilot Platform).", "Grant: Require authentication strength > Phishing-resistant MFA.", "Start in Report-only, review sign-in logs, then turn On."], "v": "2026-10-30", "n": 2, "tg": ["Copilot", "Conditional Access", "Identity", "Security"], "c": "2026-10-12"}, {"id": "ca-report-only-first", "category": "Conditional Access for AI", "title": "Roll out AI-related Conditional Access policies in report-only mode", "problem": "A new policy for AI apps could block access for thousands of users if it's wrong.", "steps": ["Create the policy with state 'Report-only'.", "Wait 1–2 weeks and review the policy impact view (no Log Analytics needed) or the Conditional Access insights and reporting workbook.", "Use the What If tool for edge cases (guests, service accounts).", "Switch to On during a maintenance window."], "v": "2026-10-30", "n": 2, "tg": ["Conditional Access", "Security"], "c": "2026-10-12"}, {"id": "ca-compliant-device-ai", "category": "Conditional Access for AI", "title": "Require a compliant or hybrid-joined device for Microsoft 365 (and Copilot)", "problem": "You don't want Copilot answers with sensitive data ending up on unmanaged personal devices.", "steps": ["Entra admin center > Entra ID > Conditional Access > Policies > New policy targeting the Copilot users group.", "Target resources: Office 365.", "Grant: Require device to be marked as compliant OR Require Microsoft Entra hybrid joined device (Require one of the selected controls).", "Exclude break-glass accounts (and Directory Synchronization Accounts if you sync); start in report-only."], "v": "2026-10-30", "n": 2, "tg": ["Copilot", "Conditional Access", "Security"], "c": "2026-10-12"}, {"id": "ca-production-lockout-mistakes", "category": "Conditional Access for AI", "title": "Conditional Access: the mistakes that cause production lockouts", "problem": "Most Conditional Access outages are self-inflicted: a block policy on All resources without exclusions, an enforced policy that never ran in report-only, a forgotten sync account. Each mistake below comes with the check that catches it before users do.", "steps": ["Mistake 1, no emergency access exclusion. Keep two cloud-only emergency access accounts in a dedicated group and exclude that group from every enforced policy. Before each change, confirm the exclusion with `Get-MgIdentityConditionalAccessPolicy | Select DisplayName, State, @{n='ExcludedGroups';e={$_.Conditions.Users.ExcludeGroups}}`.", "Mistake 2, Block combined with All resources. Microsoft warns that this combination can lock out admins, and that you can't exclude important endpoints such as Microsoft Graph. Scope block policies to the conditions you actually mean (legacy client apps, device code flow, a country list) instead of blocking everything and carving out exceptions.", "Mistake 3, going straight to On. Create every new policy, and every policy built from a template, in Report-only. Read the Report-only tab on real sign-in events, or the Insights and Reporting workbook if you stream sign-in logs to Log Analytics, and leave it there for at least a week before you switch to On.", "Mistake 4, trusting one exclusion. An excluded user can still be challenged or blocked by another policy. Run the What If tool for the excluded identities, and test with a non-admin test user in a pilot group before the organisation-wide rollout.", "Mistake 5, enforcing MFA before people can satisfy it. Make sure users have registered the required methods, protect the security info registration page with its own policy, and only then enforce strong authentication for all users.", "Mistake 6, forgetting non-interactive accounts. Exclude service accounts such as the Microsoft Entra Connect Sync account from user-scoped policies. User-scoped policies don't apply to service principals anyway; target those with Conditional Access for workload identities, and move scripts to managed identities.", "Mistake 7, a country block without the right exclusions. If you block by location, build a named location of allowed countries or regions, set it as the exclusion of the block policy, and exclude the emergency access group as well.", "Mistake 8, no protection on the policies themselves. Turn on protected actions so that creating, changing or deleting a Conditional Access policy needs a fresh strong authentication, and treat Conditional Access Administrator as a privileged role in PIM.", "Mistake 9, deleting a policy to roll back. Set the policy to Off or back to Report-only instead. A deleted policy or named location can still be restored within the 30-day soft-delete period, but turning it off is faster to reverse."], "v": "2026-10-31", "n": 2, "tg": ["Conditional Access", "Security", "PowerShell & Graph"], "c": "2026-10-31"}, {"id": "ca-block-legacy-auth", "category": "Conditional Access for AI", "title": "Block legacy authentication before you scale AI", "problem": "Legacy protocols can't do MFA, undermining every AI security control you add.", "steps": ["Entra admin center > Entra ID > Monitoring & health > Sign-in logs: add the Client app column and filter on the legacy authentication protocols (check the non-interactive sign-ins tab too).", "Entra ID > Conditional Access > Policies > New policy: All users (exclude break-glass accounts), Target resources: All resources, Conditions > Client apps: only Exchange ActiveSync clients and Other clients.", "Grant: Block access. Start in Report-only, then switch to On."], "v": "2026-10-30", "n": 1, "tg": ["Conditional Access", "Identity", "Security"], "c": "2026-10-12"}, {"id": "ca-sign-in-frequency-ai", "category": "Conditional Access for AI", "title": "Set sign-in frequency for high-risk Copilot users", "problem": "Executives with broad data access stay signed in for weeks on shared or traveling devices.", "steps": ["Policy 1: Conditional Access policy for the exec group targeting Office 365; Session: Sign-in frequency, e.g. every 12 hours.", "Policy 2 (separate): Persistent browser session = Never persistent. This control requires the policy to target All resources, so it can't live in the Office 365 policy — scope it with a device filter or to unmanaged devices.", "Turn off 'Remember MFA on trusted devices' before using sign-in frequency to avoid unexpected prompts."], "v": "2026-10-30", "n": 2, "tg": ["Copilot", "Conditional Access", "Identity", "Security"], "c": "2026-10-12"}, {"id": "ca-risk-based-ai", "category": "Conditional Access for AI", "title": "Block risky sign-ins and require password change for high user risk", "problem": "An attacker with a stolen session could use Copilot to search all accessible data quickly.", "steps": ["Requires Microsoft Entra ID P2 (ID Protection).", "Policy 1 — sign-in risk: All users, All resources, Sign-in risk High and Medium > Grant: Require authentication strength (Multifactor authentication), Session: Sign-in frequency Every time.", "Policy 2 — user risk: All users, All resources, User risk High > Grant: Require risk remediation (authentication strength and sign-in frequency Every time are applied automatically).", "Exclude break-glass accounts, start in report-only, then review the Risky users report weekly."], "v": "2026-10-30", "n": 2, "tg": ["Copilot", "Conditional Access", "Identity", "Security"], "c": "2026-10-12"}, {"id": "ca-break-glass", "category": "Conditional Access for AI", "title": "Keep break-glass accounts out of every AI-era CA policy", "problem": "Rapid policy changes for AI raise the risk of tenant lockout.", "steps": ["Create two cloud-only emergency access accounts with a permanent Global Administrator assignment.", "Register a phishing-resistant method that differs from your normal admin accounts — passkey (FIDO2) is recommended, certificate-based authentication is an alternative. This also satisfies mandatory MFA.", "Put them in a dedicated group (e.g. EmergencyAccess) and exclude it from every Conditional Access policy that blocks or restricts sign-in (report-only policies don't need the exclusion).", "Alert on every sign-in and audit event for these accounts (Azure Monitor/Log Analytics).", "Test sign-in at least every 90 days (e.g. quarterly)."], "v": "2026-10-30", "n": 1, "tg": ["Conditional Access", "Security"], "c": "2026-10-12"}, {"id": "intune-devices-stay-noncompliant", "category": "Intune & devices for AI", "title": "Why Intune devices stay non-compliant: causes and diagnosis", "problem": "A device that is configured correctly can still show Not compliant, In grace period or Not evaluated, and Conditional Access blocks it. The usual causes are tenant-wide compliance settings, check-in timing, settings in Error, and a second policy you didn't look at.", "steps": ["Check the tenant-wide settings first: Intune admin center > Endpoint security > Device compliance > Compliance policy settings. If Mark devices with no compliance policy assigned as is set to Not compliant, every device that doesn't receive a policy is non-compliant, and Company Portal shows No compliance policies have been assigned.", "Check the Compliance status validity period (default 30 days, range 1–120). A device that doesn't report all of its compliance policies within that period is treated as non-compliant. Look for the Is active setting under Devices > Monitor > Setting compliance.", "Check the built-in default compliance checks. A device is non-compliant if it has no applicable compliance policy assigned, if it isn't active (it hasn't kept in contact with Intune), or if the enrolled user no longer exists or has no valid Intune license.", "Find out which policy fails. A per-policy report only shows compliance with that policy, and the overall device state can be Not compliant because of another policy. When several compliance policies apply, Intune uses the most secure one. Open the device, review every compliance policy on it, and drill into Per-setting status.", "Look for settings in Error. The device keeps its previous compliance state for up to seven days while a setting reports Error. After that it becomes Not compliant, or In grace period if the policy has a grace period. A device that was compliant can therefore lose access a week after the real problem started.", "Understand Not evaluated. It is the first state after enrollment, and it also appears for devices with no compliance policy and no trigger, devices that haven't checked in since the policy changed, and devices without user affinity, such as DEP devices without affinity, Android Enterprise dedicated devices and devices enrolled with a device enrollment manager account.", "Force a check-in before you conclude anything. Reports reflect the last check-in, and a device can take up to 24 hours to appear in a policy's device status. Use Devices > All devices > select the device > Sync, then re-read the report.", "Query the state at scale with Microsoft Graph: `GET https://graph.microsoft.com/v1.0/deviceManagement/managedDevices?$filter=complianceState eq 'noncompliant'&$select=deviceName,userPrincipalName,lastSyncDateTime,complianceState`. Possible values for `complianceState` include `inGracePeriod`, `error`, `conflict` and `unknown`, and an old `lastSyncDateTime` points to a check-in problem rather than a setting problem.", "Check settings the OS doesn't fix by itself. Settings such as device encryption on Windows, Android and macOS are quarantined rather than remediated, so the device stays blocked until the user or a configuration profile actually fixes the setting. Company Portal tells the user what is wrong."], "v": "2026-10-31", "n": 4, "tg": ["Conditional Access", "Intune", "PowerShell & Graph"], "c": "2026-10-31"}, {"id": "intune-deploy-m365-apps-channel", "category": "Intune & devices for AI", "title": "Deploy Microsoft 365 Apps on Current or Monthly Enterprise Channel with Intune", "problem": "Copilot features arrive late or not at all on devices on older Microsoft 365 Apps builds or the wrong update channel.", "steps": ["Intune admin center > Apps > All Apps > Create > Microsoft 365 Apps: Windows 10 and later.", "Choose the update channel: Current Channel or Monthly Enterprise Channel.", "Assign to the Copilot pilot device/user group.", "Verify version with the Microsoft 365 Apps admin center inventory."], "v": "2026-10-30", "n": 4, "tg": ["Copilot", "Intune"], "c": "2026-10-12"}, {"id": "intune-compliance-baseline", "category": "Intune & devices for AI", "title": "Create a Windows compliance policy that CA can rely on", "problem": "Device-based Conditional Access is meaningless if compliance policies are weak.", "steps": ["Intune > Devices > Compliance > Create policy > Windows 10 and later.", "Require BitLocker, Secure Boot, a minimum OS version, and Microsoft Defender Antimalware.", "Optionally require the device to be at or under a machine risk score from Defender for Endpoint.", "Set actions for noncompliance (Mark device noncompliant after a grace period)."], "v": "2026-10-30", "n": 2, "tg": ["Conditional Access", "Intune"], "c": "2026-10-12"}, {"id": "intune-app-protection-copilot", "category": "Intune & devices for AI", "title": "Protect Copilot on iOS/Android with app protection policies", "problem": "Users want Copilot and Microsoft 365 apps on personal phones without enrolling them.", "steps": ["Intune > Apps > App protection policies > Create (iOS/iPadOS and Android).", "Target the Microsoft Copilot app (formerly the Microsoft 365 Copilot app) and the Microsoft 365 apps (Outlook, Teams, Word, etc.).", "Data protection: restrict cut/copy/paste to policy-managed apps, block save to personal storage.", "Pair with a Conditional Access policy granting 'Require app protection policy' (or approved client app) for iOS/Android."], "v": "2026-10-30", "n": 3, "tg": ["Copilot", "Intune"], "c": "2026-10-12"}, {"id": "intune-copilot-key-windows", "category": "Intune & devices for AI", "title": "Manage the Copilot experience on Windows devices", "problem": "Copilot on Windows changes frequently and admins need to control what users see.", "steps": ["Entra users get the Microsoft Copilot app (previously the Microsoft 365 app) pinned; licensed users can switch between Work and Web.", "Set what the Copilot key (or Win+C) opens with the WindowsAI CSP `./User/Vendor/MSFT/Policy/Config/WindowsAI/SetCopilotHardwareKey` (GPO: Windows Components > Windows Copilot > Set Copilot Hardware Key).", "Block the consumer Copilot app (package MICROSOFT.COPILOT) with AppLocker, or remove it per device; deploy the apps you want with Intune per group.", "Communicate to users what the Copilot key opens in your tenant."], "v": "2026-10-30", "n": 1, "tg": ["Copilot", "Intune"], "c": "2026-10-12"}, {"id": "intune-windows-autopatch", "category": "Intune & devices for AI", "title": "Keep AI-ready devices current with Windows Autopatch", "problem": "Copilot and security features depend on current Windows and Office builds.", "steps": ["Register devices in Windows Autopatch and organize them with Autopatch groups and update rings.", "Include Microsoft 365 Apps updates (Autopatch targets Monthly Enterprise Channel), plus Edge and Teams.", "Monitor Intune update reports for devices falling behind."], "v": "2026-10-30", "n": 1, "tg": ["Copilot", "Intune"], "c": "2026-10-12"}, {"id": "intune-edge-policies-ai", "category": "Intune & devices for AI", "title": "Control generative AI in Microsoft Edge with Intune settings catalog", "problem": "You want enterprise data protection in the browser and to manage Copilot in the Edge sidebar.", "steps": ["Intune > Devices > Configuration > Create > New policy > Windows 10 and later > Settings catalog, then search for Microsoft Edge.", "Configure the Copilot policies you decided on, e.g. EdgeCopilotEnabled, Microsoft365CopilotChatIconEnabled (toolbar icon) and EdgeEntraCopilotPageContext (page context for Entra profiles).", "Assign to device groups and verify at edge://policy."], "v": "2026-10-30", "n": 2, "tg": ["Copilot", "Intune"], "c": "2026-10-12"}, {"id": "autopilot-device-preparation-entra-join", "category": "Intune & devices for AI", "title": "Windows Autopilot device preparation: user-driven Entra join with a provisioning-owned device group", "problem": "Device preparation replaces the classic Autopilot profile + ESP pair for Windows 11 Entra join, but it silently does nothing if the device group, its owner or the app context is wrong. Build it so the essential apps land during OOBE and everything else follows after the desktop.", "steps": ["Pick the engine per device: device preparation covers user-driven and automatic mode, Entra join only, Windows 11 (24H2, or 22H2/23H2 with KB5035942). Need hybrid join, pre-provisioning, self-deploying, Autopilot Reset, Windows 10 or more than 25 apps during OOBE? Stay on classic Autopilot profiles.", "Prerequisites: Windows automatic Intune enrollment is configured and the target users are allowed to join devices to Microsoft Entra ID.", "Make sure the Intune Provisioning Client service principal exists (app ID `f1346770-5b25-470b-88bd-d5744ab7952c`; some tenants show it as Intune Autopilot ConfidentialClient): `Connect-MgGraph -Scopes Application.ReadWrite.All` then `New-MgServicePrincipal -AppId f1346770-5b25-470b-88bd-d5744ab7952c`. A 409 Request_MultipleObjectsWithSameKeyValue means it is already there.", "Create a dedicated assigned security device group (not dynamic, not role-assignable), e.g. `$g = New-MgGroup -DisplayName 'APDP-UserDriven-Devices' -MailEnabled:$false -MailNickname 'apdp-ud-devices' -SecurityEnabled -IsAssignableToRole:$false`.", "Make the provisioning service principal the group owner: `$sp = Get-MgServicePrincipal -Filter \"appId eq 'f1346770-5b25-470b-88bd-d5744ab7952c'\"` then `New-MgGroupOwnerByRef -GroupId $g.Id -BodyParameter @{'@odata.id'=\"https://graph.microsoft.com/v1.0/directoryObjects/$($sp.Id)\"}`. Devices are added to this group during the deployment; you don't add members yourself.", "Create a user group for the people who will run setup, and assign every essential app and platform script to the device group (not the user group). Apps must install in System context; scripts must have Run this script using the logged on credentials = No.", "Intune admin center > Devices > Windows > Enrollment > Device preparation policies > Create > User Driven. Device group page: the device group. Configuration: Deployment mode User-driven, Deployment type Single user, Join type Microsoft Entra joined, User account type Standard User (removes the auto-granted local admin before the desktop).", "Set Minutes allowed before showing installation error (15–720, covers the whole run), a custom error message, Show link to diagnostics = Yes, and decide on Allow users to skip setup after multiple attempts. Under Apps select up to 25 essential apps (LOB, Win32, WinGet-backed Store, Microsoft 365, Enterprise App Catalog; LOB and Win32 can be mixed) and under Scripts up to 10 scripts.", "Assignments: the user group. If several policies target the same user, order them in the Priority column (lowest number wins); a device-based assignment beats a user-based one.", "If an enrollment restriction blocks personal Windows devices, every device needs a corporate identifier or device association before first boot (see the related registration recipe). OOBE tweaks such as hiding the EULA/privacy pages and the device name template only work for associated devices.", "Run a pilot device and watch Devices > Monitor > Windows Autopilot device preparation deployments: phase, per-app and per-script status, and deployment time in near real time."], "v": "2026-10-31", "n": 7, "tg": ["Identity", "Intune", "PowerShell & Graph"], "c": "2026-10-31"}, {"id": "autopilot-register-hash-corporate-identifiers", "category": "Intune & devices for AI", "title": "Pre-stage Windows devices for Autopilot: hardware hash import vs corporate identifiers, by CSV or Graph", "problem": "Classic Autopilot needs a registered hardware hash; device preparation with personal enrollment blocked needs a corporate identifier instead. Mixing them up is the most common reason a new device enrolls as personal, gets blocked, or runs the wrong flow.", "steps": ["Decide per fleet: classic Autopilot profile = register the hardware hash (ideally by OEM/reseller, own upload mainly for test and limited cases). Device preparation = no registration; upload a Windows corporate identifier (manufacturer, model, serial) only if an enrollment restriction blocks personal Windows devices, or use device association.", "Collect a hash on a running device (elevated): `Install-Script -Name Get-WindowsAutopilotInfo` then `Get-WindowsAutopilotInfo -OutputFile AutopilotHWID.csv`. In OOBE: Shift+F10, `powershell.exe`, then `Get-WindowsAutopilotInfo -Online` with an Intune Administrator (first run asks for Graph consent). Windows 11 OOBE can also export it from the diagnostics page (Ctrl+Shift+D).", "Merge into one CSV, max 500 rows per batch, header exactly `Device Serial Number,Windows Product ID,Hardware Hash,Group Tag,Assigned User`: no extra columns, no quotes, ANSI encoding, edited in a plain-text editor, never saved from Excel.", "Import: Intune admin center > Devices > Windows > Enrollment > Windows Autopilot > Devices > Import, then Sync and Refresh until the rows appear. Wait for each batch to finish before the next.", "Scripted import: `POST https://graph.microsoft.com/v1.0/deviceManagement/importedWindowsAutopilotDeviceIdentities/import` with `importedWindowsAutopilotDeviceIdentities[]` carrying `serialNumber`, `hardwareIdentifier` (Base64 hash), optional `groupTag` and `assignedUserPrincipalName`. Permission: `DeviceManagementServiceConfig.ReadWrite.All`. Poll `state.deviceImportStatus` and `deviceErrorName`.", "Verify registrations: `GET https://graph.microsoft.com/v1.0/deviceManagement/windowsAutopilotDeviceIdentities` (filter on serial) and confirm each device has the intended group tag and an assigned profile.", "Corporate identifiers for Windows: build a CSV without header, one `Manufacturer,Model,Serial` line per device (periods removed from the serial, max 5,000 rows / 5 MB, one identifier type per file). Read the values with `Get-CimInstance Win32_ComputerSystem | ForEach-Object { $_.Manufacturer, $_.Model, (Get-CimInstance Win32_BIOS).SerialNumber -join ',' }`.", "Upload: Devices > Enrollment > Corporate device identifiers > Add > Upload CSV file > Manufacturer, model, and serial number (Windows only). Manual entry isn't available for Windows. Above 10 CSV uploads, use Graph: `POST https://graph.microsoft.com/beta/deviceManagement/importedDeviceIdentities/importDeviceIdentityList` (beta) with `DeviceManagementServiceConfig.ReadWrite.All`.", "Only now enable or confirm the device platform restriction that blocks personally owned Windows devices, and track identifier status (Enrolled, Not contacted, Failed)."], "v": "2026-10-31", "n": 8, "tg": ["Intune", "PowerShell & Graph"], "c": "2026-10-31"}, {"id": "autopilot-troubleshoot-enrollment", "category": "Intune & devices for AI", "title": "Troubleshoot Windows Autopilot enrollment: event IDs, profile registry, MDM diagnostics and auto-collected logs", "problem": "When Autopilot stalls in OOBE the error page rarely names the cause. Work the flow in order (profile, tenant match, Entra join, MDM enrollment, ESP/apps) and pull the evidence from the device and from Intune instead of guessing.", "steps": ["Locate the failure in the flow: network > profile download > user auth > Entra join > automatic MDM enrollment > settings/apps (ESP for classic, tracked apps/scripts for device preparation). If you see the ESP on a device meant for device preparation, it's running classic Autopilot.", "Device preparation: start at Devices > Monitor > Windows Autopilot device preparation deployments; the device detail shows the last phase and which app or script failed or was Skipped.", "Classic Autopilot on Windows 11: enable the diagnostics page in the ESP profile (Show app and profile configuration progress = Yes, Turn on log collection and diagnostics page for end users = Yes) and open it in OOBE with Ctrl+Shift+D.", "In OOBE, Shift+F10 gives a prompt. Read the Autopilot channel: `Get-WinEvent -LogName 'Microsoft-Windows-ModernDeployment-Diagnostics-Provider/Autopilot' -MaxEvents 50 | Format-Table TimeCreated,Id,Message -Wrap`. Key IDs: 807 ZtdDeviceIsNotRegistered, 809/815 no assigned profile, 908 serial or product key mismatch, 171/172 TPM attestation (self-deploying/pre-provisioning), 163 profile already present.", "Check what the device actually received: `Get-ItemProperty HKLM:\\SOFTWARE\\Microsoft\\Provisioning\\Diagnostics\\Autopilot`. CloudAssignedTenantDomain blank or IsAutopilotDisabled = 1 means no registration or no profile download; TenantMatched = 0 means the user signed in to a different tenant than the device is registered to.", "MDM side: `Get-WinEvent -LogName 'Microsoft-Windows-DeviceManagement-Enterprise-Diagnostics-Provider/Admin' -MaxEvents 50`, plus `dsregcmd /status` for join state. Enable the Debug channel in Event Viewer when Admin isn't enough.", "Bundle everything: `mdmdiagnosticstool.exe -area \"DeviceEnrollment;DeviceProvisioning;Autopilot\" -zip C:\\Users\\Public\\Documents\\MDMDiagReport.zip`. The zip holds Autopilot and provisioning ETLs, MDMDiagHtmlReport.html, a registry dump and the enterprise diagnostics evtx.", "From the portal: Intune auto-captures logs on Autopilot failure (one set per device per day, kept 28 days) under the device > Diagnostics > Download; for enrolled corporate devices use Collect diagnostics (bulk up to 25). Graph can't collect or download these.", "After a profile change, restart from OOBE with `shutdown.exe /r /t 0` so the device downloads the profile again."], "v": "2026-10-31", "n": 6, "tg": ["Identity", "Intune", "PowerShell & Graph"], "c": "2026-10-31"}, {"id": "purview-oversharing-assessment", "category": "Purview, DLP & data security for Copilot", "title": "Find oversharing before Copilot does: data security posture for AI", "problem": "Copilot respects permissions, so content shared with 'Everyone' becomes discoverable through Copilot.", "steps": ["Open Microsoft Purview > Data Security Posture Management (DSPM, or DSPM for AI (classic)).", "Review the default weekly data risk assessment for oversharing, or create a custom data risk assessment for specific sites.", "Review top sites with sensitive content shared broadly.", "Remediate: restrict access, apply labels, or use Restricted Content Discovery."], "v": "2026-10-30", "n": 2, "tg": ["Copilot", "Purview & DLP", "Security"], "c": "2026-10-12"}, {"id": "sharepoint-restricted-content-discovery", "category": "Purview, DLP & data security for Copilot", "title": "Hide specific sites from Copilot with Restricted Content Discovery", "problem": "A few sensitive sites should not be surfaced by Copilot or org-wide search.", "steps": ["Requires a Microsoft Copilot license in the tenant and SharePoint Advanced Management (included with Microsoft Copilot or as an add-on).", "SharePoint admin center > Sites > Active sites > select the site > Settings > turn on 'Restrict content from Microsoft Copilot' > Save.", "Or PowerShell: `Connect-SPOService -Url https://contoso-admin.sharepoint.com` then `Set-SPOSite -Identity <siteUrl> -RestrictContentOrgWideSearch $true`", "Verify after reindexing (can take time for large sites)."], "v": "2026-10-30", "n": 2, "tg": ["Copilot", "Purview & DLP", "Security", "PowerShell & Graph"], "c": "2026-10-12"}, {"id": "purview-sensitivity-labels-copilot", "category": "Purview, DLP & data security for Copilot", "title": "Make Copilot respect sensitivity labels and encryption", "problem": "You need to know how labeled and encrypted content is handled in Copilot responses.", "steps": ["Publish sensitivity labels to users.", "Copilot applies the highest-priority label of referenced content to new content in supported scenarios (and it replaces a lower-priority manual label).", "For encrypted content, Copilot needs the user to have both EXTRACT and VIEW usage rights.", "To stop Copilot summarizing files at rest, use labels that apply encryption without the EXTRACT right. Test with a pilot user."], "v": "2026-10-30", "n": 2, "tg": ["Copilot", "Purview & DLP", "Security"], "c": "2026-10-12"}, {"id": "purview-dlp-copilot-location", "category": "Purview, DLP & data security for Copilot", "title": "Use a DLP policy to stop Copilot processing labeled content", "problem": "Highly confidential files should not be summarized by Copilot at all.", "steps": ["Purview portal > Data loss prevention > Policies > + Create policy > Custom template > Custom policy.", "On Locations, turn on 'Microsoft 365 Copilot and Copilot Chat'.", "Rule condition: Content contains > Sensitivity labels > 'Highly Confidential'.", "Action: Prevent Copilot from processing content. Test in simulation mode first."], "v": "2026-10-30", "n": 1, "tg": ["Copilot", "Purview & DLP", "Security"], "c": "2026-10-12"}, {"id": "purview-audit-copilot", "category": "Purview, DLP & data security for Copilot", "title": "Audit Copilot interactions in Microsoft Purview", "problem": "Security asks: who used Copilot, when, and which resources were referenced?", "steps": ["Make sure auditing is on (Exchange Online PowerShell): `Connect-ExchangeOnline` then `Get-AdminAuditLogConfig | FL UnifiedAuditLogIngestionEnabled`", "Purview > Audit > search with activity 'Interacted with Copilot' (record type CopilotInteraction).", "Export results; files, sites and other resources Copilot accessed are listed in the AuditData.", "Or `Search-UnifiedAuditLog -RecordType CopilotInteraction -StartDate (Get-Date).AddDays(-7) -EndDate (Get-Date)`"], "v": "2026-10-30", "n": 2, "tg": ["Copilot", "Purview & DLP", "Security", "PowerShell & Graph"], "c": "2026-10-12"}, {"id": "purview-retention-copilot", "category": "Purview, DLP & data security for Copilot", "title": "Set retention for Copilot interactions", "problem": "Compliance requires a defined retention period for AI prompts and responses.", "steps": ["Purview > Data lifecycle management > Retention policies > New retention policy.", "Select the 'Microsoft Copilot experiences' location (Microsoft 365 Copilot, Copilot Studio and other Microsoft Copilots).", "Set retain/delete period and scope.", "Document in your records management plan."], "v": "2026-10-30", "n": 1, "tg": ["Copilot", "Purview & DLP", "Security"], "c": "2026-10-12"}, {"id": "pim-least-privilege-daily-ops", "category": "Identity & threat protection", "title": "PIM: least privilege without breaking daily operations", "problem": "Moving every admin to eligible assignments in Privileged Identity Management cuts standing access, but badly chosen role settings lock admins out, flood approvers or make people activate five roles every morning. These settings keep least privilege and keep the work moving.", "steps": ["Inventory first. List every Microsoft Entra role assignment with `GET https://graph.microsoft.com/v1.0/roleManagement/directory/roleAssignments?$expand=principal` and flag roles with the PRIVILEGED label. Aim for fewer than five Global Administrators and fewer than ten privileged role assignments.", "Keep zero permanently active assignments except for the two cloud-only emergency access accounts, which stay permanently active Global Administrators. Make everyone else eligible, and use cloud-only accounts, not on-premises synced accounts, for admin roles.", "Set role settings per role, because every assignment of a role follows that role's settings. Change them under ID Governance > Privileged Identity Management > Microsoft Entra roles > Roles > select the role > Role settings > Edit. You need at least Privileged Role Administrator.", "Tier the activation rules. For the highest-impact roles (for example Global Administrator and Privileged Role Administrator), use a short activation maximum duration, require justification and require approval. For daily support roles, use a longer duration (the range is 1–24 hours), require MFA and justification, and skip approval so the help desk isn't blocked.", "Configure approvers explicitly, at least two per role. If approval is required and no approvers are set, active Privileged Role Administrators and Global Administrators become the default approvers. If all of them are only eligible, the tenant can lock itself out.", "For strong authentication at activation, use On activation, require Microsoft Entra Conditional Access authentication context with an authentication strength. Create and enable the Conditional Access policy for that context first, and scope it to all users or the eligible users, not to the directory role, because the user doesn't hold the role yet when activating.", "Remove the 'activate six roles every morning' problem with PIM for Groups. Assign the roles a job needs to a role-assignable group, and make the admin an eligible member of that group, so one activation covers all of them.", "Use time-bound eligible assignments with an end date for projects and contractors, and run recurring access reviews of privileged roles to remove eligibility that is no longer needed.", "Watch it. Configure PIM security alerts, keep notifications on for activations of highly privileged roles, and read the PIM audit history every week. Audit history goes back 30 days, so export it monthly."], "v": "2026-10-31", "n": 4, "tg": ["Identity", "Security", "PowerShell & Graph"], "c": "2026-10-31"}, {"id": "exchange-ews-cross-tenant-sharing-inventory", "category": "Identity & threat protection", "title": "Find cross-tenant Free/Busy, MailTips and calendar sharing that still depends on EWS", "problem": "Organization Relationships and Sharing Policies that share Free/Busy, MailTips or calendars with other Microsoft 365 tenants depend on EWS, which Exchange Online is switching off. Before you move them to Microsoft 365 Cross-Tenant Access Policy you need an inventory of what exists, who it applies to and which partners are cloud-hosted.", "steps": ["Connect to Exchange Online PowerShell with an account that has the Organization Management role. Set `$FormatEnumerationLimit = -1` so long domain lists are not truncated.", "List enabled Organization Relationships: `Get-OrganizationRelationship | Where-Object { $_.Enabled } | Format-List Name, DomainNames, FreeBusyAccessEnabled, FreeBusyAccessLevel, FreeBusyAccessScope, MailTipsAccessEnabled, MailTipsAccessLevel, MailTipsAccessScope, TargetSharingEpr, TargetAutodiscoverEpr, TargetApplicationUri`.", "For each relationship with Free/Busy or MailTips enabled, decide whether the partner is in Microsoft 365: Microsoft's guide says a TargetSharingEpr or TargetAutodiscoverEpr containing outlook.com, office365.com or office365.us indicates a Microsoft 365-hosted partner; other values may indicate on-premises Exchange.", "List Availability Address Spaces with `Get-AvailabilityAddressSpace | Format-List ForestName, AccessMethod, TargetAutodiscoverEpr, TargetServiceEpr, TargetTenantId`. Microsoft notes these do not depend on EWS for Microsoft 365 partners, so they are optional to migrate.", "List Sharing Policies with `Get-SharingPolicy | Format-List Name, Enabled, Domains, Default` and note every domain rule with CalendarSharingFreeBusySimple, Detail or Reviewer, plus any Anonymous rule (published calendars).", "Count which mailboxes each policy actually applies to: `Get-EXOMailbox -ResultSize Unlimited -RecipientTypeDetails UserMailbox,SharedMailbox -Properties SharingPolicy | Group-Object SharingPolicy | Select-Object Name, Count`.", "Record each in-scope partner's Entra tenant ID (ask their admin) and whether they will also migrate — the new policy is inbound-only, so two-way sharing needs a policy in both tenants.", "Hand the inventory to the migration: Free/Busy and MailTips can move to Cross-Tenant Access Policy now; keep calendar-sharing policies until XTAP calendar sharing has reached your tenant (Microsoft's worldwide target is 23 November 2026)."], "v": "2026-11-09", "n": 3, "tg": ["Identity", "Security", "PowerShell & Graph"], "c": "2026-11-09"}, {"id": "entra-sms-voice-retirement-passkeys", "category": "Identity & threat protection", "title": "Move users off SMS and voice MFA before Microsoft-provided SMS and voice retire on 1 February 2027", "problem": "Microsoft-provided SMS and voice authentication retires on 1 February 2027 (1 July 2027 for Global Administrators and external users). After that date, users whose only MFA method is SMS or voice get a blocking prompt to register a passkey before they can sign in.", "steps": ["Find who still depends on SMS or voice: run the PowerShell script or the SMS/voice usage analyzer linked from Microsoft's retirement guide (needs Global Reader, Authentication Policy Administrator or Security Reader).", "Put those users in a security group so every following step can target them.", "Entra admin center > Entra ID > (Security >) Authentication methods > Policies: make sure Passkey (FIDO2) is enabled and that the group is in scope. Synced passkeys and device-bound passkeys (Microsoft Authenticator, FIDO2 keys, Windows) are both supported.", "Entra ID > Authentication methods > Registration campaign: set State to Microsoft managed and target the group, so users are nudged to register a passkey the next time they complete MFA. Choose Enabled instead if you need to control the targeted method or how often users can snooze.", "Only for user segments with a documented regulatory or operational need, pick a telephony provider in Microsoft Security Store (selectable from 30 October 2026) and pilot it. Microsoft recommends finishing setup at least 4 weeks before 1 February 2027.", "Tell users what is coming: since 1 September 2026, users enabled for SMS or voice are auto-enabled for passkeys and prompted to register one at MFA sign-in. They can skip the prompt until their retirement date, but not after it.", "Do Global Administrators first even though their deadline is later: your most privileged accounts should be on phishing-resistant MFA anyway."], "v": "2026-10-30", "n": 8, "tg": ["Identity", "Security", "News / Retirement"], "c": "2026-10-30"}, {"id": "ca-managed-risk-remediation-policy", "category": "Identity & threat protection", "title": "Check the Microsoft-managed 'Require risk remediation for high-risk users' policy that just switched on", "problem": "In Entra ID P2 tenants Microsoft created a managed Conditional Access policy in report-only mode the week of 28 September 2026. If nobody touched it, it switched to On automatically the week of 28 October 2026, so high-risk users are now forced to self-remediate.", "steps": ["Entra admin center > Entra ID > Conditional Access > Policies: open 'Require risk remediation for high-risk users' (Microsoft-managed) and note the security group that was created with it.", "Open the Policy impact tab to see which sign-ins the policy affected while it was in report-only.", "Exclude your break-glass/emergency access accounts, or narrow the scope by changing the membership of the policy's security group.", "Make sure the users in scope are registered for MFA so they can self-remediate. In hybrid tenants, self-remediation by secure password change relies on password hash sync.", "Decide on the state: leave it On, or set it to Off if you already run your own user-risk policy. If you need more changes than exclusions and state, use Duplicate and build your own copy.", "Afterwards, check Entra ID > Monitoring & health > Sign-in logs, filtered on Conditional Access, for users stuck in remediation."], "v": "2026-10-30", "n": 4, "tg": ["Conditional Access", "Identity", "Security", "News / Retirement"], "c": "2026-10-30"}, {"id": "sharepoint-otp-retirement-b2b", "category": "Identity & threat protection", "title": "Stop 'access denied' for external users as SharePoint one-time passcode retires", "problem": "SharePoint Online one-time passcode (OTP) authentication began retiring in commercial tenants in mid-October 2026, and the retirement should be complete by the end of November 2026. External users without a matching Entra B2B guest account then get 'access denied' on previously shared 'Specific people' links.", "steps": ["Find who is affected: run the sharing report on key sites (Settings > Site usage > Shared with external users > Run report) or in OneDrive, and use sharing auditing in the audit log. Microsoft Graph Data Connect site sharing reports work at larger scale.", "Create the missing guest accounts in advance: Entra ID > Users > Invite external user, using the same email address as the original sharing link (needs at least Guest Inviter or User Administrator).", "Alternatively, a user with sharing permissions can share or reshare one file, folder or site with the person. That creates the guest account and restores access to everything shared before, so items don't need to be reshared one by one.", "Check Entra ID > External Identities > External collaboration settings so the people who share are allowed to invite guests. Assign the Guest Inviter role where needed.", "Keep Entra B2B email one-time passcode enabled as the fallback for guests without another sign-in method. It is not being retired.", "Compare your SharePoint domain allow/deny lists with the Entra B2B allow/deny list, since the Entra list now applies to SharePoint sharing too.", "Warn the help desk: older links can now fail for external partners."], "v": "2026-10-30", "n": 7, "tg": ["Identity", "Security", "News / Retirement"], "c": "2026-10-30"}, {"id": "defender-teams-zap-qr-phishing", "category": "Identity & threat protection", "title": "Catch phishing in Teams chats: ZAP for Teams, QR-code URL detection and user reporting", "problem": "Since early October 2026 (rollout completes early November), Defender for Office 365 also extracts the URLs hidden in QR codes in Teams messages after delivery and puts a warning on malicious ones. With ZAP for Teams on, eligible malicious internal messages can be blocked.", "steps": ["Microsoft Defender portal > Settings > Email & collaboration > Microsoft Teams protection (security.microsoft.com/securitysettings/teamsProtectionPolicy): check that the Zero-hour auto purge (ZAP) toggle is On.", "On the same page, pick the quarantine policies for malware and high-confidence phishing, and add exclusions only if you really need them. Exclusions apply to recipients, not senders.", "PowerShell alternative: `Get-TeamsProtectionPolicy | Format-List Name,ZapEnabled` and `Set-TeamsProtectionPolicy -Identity \"Teams Protection Policy\" -ZapEnabled $true`.", "Turn on user reporting in two places: 'Report a security concern' in the Teams admin center messaging policies (plus calling and meeting reporting if you want them), and 'Monitor reported items in Microsoft Teams' on the Teams user reported settings page (security.microsoft.com/securitysettings/teamsUserSubmission). Existing tenants need to enable the Defender setting themselves.", "Hunt for QR-code detections in Advanced Hunting: `MessageUrlInfo | where UrlLocation == \"QRCode\"`.", "Tell the SOC that users can now also report Teams calls, meetings and meeting participants, so these reports show up on the Submissions page."], "v": "2026-10-30", "n": 5, "tg": ["Identity", "Security", "News / Retirement", "PowerShell & Graph"], "c": "2026-10-30"}, {"id": "copilot-studio-environment-strategy", "category": "Agents & Copilot Studio governance", "title": "Set up a Power Platform environment strategy for Copilot Studio agents", "problem": "Makers build agents in the default environment with no governance.", "steps": ["Define environments: Default (personal productivity), Dev/Test/Prod for shared agents.", "Turn on environment routing in the Power Platform admin center to send new makers to their own personal developer environment.", "Restrict who can create environments in Power Platform admin center."], "v": "2026-10-30", "n": 2, "tg": ["Copilot", "Agents"], "c": "2026-10-12"}, {"id": "copilot-studio-dlp", "category": "Agents & Copilot Studio governance", "title": "Use Power Platform data policies to govern Copilot Studio connectors", "problem": "Agents can connect to external services and leak data.", "steps": ["Power Platform admin center > Security > Data and privacy > Data policy > + New policy.", "Classify connectors into Business, Non-business, and Blocked.", "Use the Copilot Studio connectors (e.g. 'Chat without Microsoft Entra ID authentication in Copilot Studio', Direct Line and other publishing channels, knowledge sources) to block risky use cases.", "Apply to all environments, with exceptions for dev."], "v": "2026-10-30", "n": 3, "tg": ["Copilot", "Agents"], "c": "2026-10-12"}, {"id": "agents-inventory-admin-center", "category": "Agents & Copilot Studio governance", "title": "Inventory and manage agents in the Microsoft 365 admin center", "problem": "You don't know which agents exist or who uses them.", "steps": ["Microsoft 365 admin center > Agents > Overview for a summary, then All agents > Registry for the full inventory (in tenants that don't have the new Agents section yet: Copilot > Agents).", "Review each agent's publisher type (Microsoft, external partner, published by your org, shared by creator), owner, availability and risk signals.", "Approve or reject requests under All agents > Requests, assign owners to ownerless agents, and block or delete agents that violate policy.", "Use the AI Administrator role for day-to-day agent management instead of Global Administrator."], "v": "2026-10-30", "n": 3, "tg": ["Agents"], "c": "2026-10-12"}, {"id": "agents-integrated-apps", "category": "Agents & Copilot Studio governance", "title": "Control which users can install agents and apps (Integrated apps)", "problem": "Users install third-party agents and Teams apps that access org data.", "steps": ["Microsoft 365 admin center > Settings > Integrated apps: review deployed apps and agents, the Requested apps tab, and who each app is available to.", "Teams admin center > Teams apps > Manage apps: allow or block apps and agents per app and assign them to users/groups (app centric management). Org-wide app settings blocks all third-party apps.", "Microsoft Entra admin center > Entra ID > Enterprise apps > Consent and permissions: restrict user consent and turn on the admin consent workflow so users can request apps."], "v": "2026-10-30", "n": 3, "tg": ["Agents"], "c": "2026-10-12"}, {"id": "agents-restrict-blueprint-creation", "category": "Agents & Copilot Studio governance", "title": "Decide who can create agents in Entra before default users get the right on 4 November 2026", "problem": "From 4 November 2026 (rollout through late November), users without any Entra role can create agent identity blueprints, and the agents built from them, unless you set 'Users can create agent blueprints' to No.", "steps": ["Sign in to the Entra admin center as at least a Cloud Application Administrator.", "Entra ID > Users > User settings > Default user role permissions: set 'Users can create agent blueprints' to No and save. You can do this now; it takes effect when the rollout reaches your tenant.", "Give named builders the Agent ID Developer role, which lets them create blueprints and blueprint principals. Reserve Agent ID Administrator for people who must add a secret or certificate to a blueprint.", "Review 'Users can register applications' at the same time. The new setting is independent of it.", "Review blueprint owners regularly: owners can create agent identities from their blueprint without an Agent ID role."], "v": "2026-10-30", "n": 3, "tg": ["Identity", "Agents", "News / Retirement"], "c": "2026-10-30"}, {"id": "entra-user-consent-restrict", "category": "Agents & Copilot Studio governance", "title": "Restrict user consent for apps and AI tools", "problem": "Employees grant third-party AI tools access to mail and files via OAuth consent.", "steps": ["Entra admin center > Entra ID > Enterprise apps > Consent and permissions > User consent settings.", "Select 'Allow user consent for apps from verified publishers, for selected permissions' or 'Do not allow user consent'.", "Enable the admin consent workflow (Admin consent settings) so users can request access."], "v": "2026-10-30", "n": 2, "tg": ["Identity", "Agents"], "c": "2026-10-12"}, {"id": "copilot-studio-auth", "category": "Agents & Copilot Studio governance", "title": "Require authentication for Copilot Studio agents", "problem": "An agent published to a website without auth exposes internal knowledge.", "steps": ["In Copilot Studio open the agent > Settings > Security > Authentication and choose 'Authenticate with Microsoft' for internal agents (or 'Authenticate manually' for other identity providers).", "Enforce it tenant-wide: in a Power Platform data policy, block the connector 'Chat without Microsoft Entra ID authentication in Copilot Studio' — makers then can't pick 'No authentication'.", "Review published channels for each agent (e.g. block Direct Line or demo website channels you don't use)."], "v": "2026-10-30", "n": 2, "tg": ["Copilot", "Agents"], "c": "2026-10-12"}, {"id": "copilot-usage-report", "category": "Licensing & reporting", "title": "Track active Copilot usage with the Microsoft 365 usage report", "problem": "Management asks if the Copilot investment is used.", "steps": ["Microsoft 365 admin center > Reports > Usage > Microsoft Copilot > Copilot (Usage tab).", "Review enabled vs active users, active users rate and adoption by app; data arrives within about 48 hours.", "Reallocate licenses from users inactive for 30+ days (after checking with managers)."], "v": "2026-10-30", "n": 2, "tg": ["Copilot", "Licensing"], "c": "2026-10-12"}, {"id": "copilot-usage-graph", "category": "Licensing & reporting", "title": "Pull Copilot usage via Microsoft Graph reports API", "problem": "You want Copilot usage in Power BI or a scheduled report.", "steps": ["Grant Reports.Read.All (application, or delegated for a user with e.g. Reports Reader or AI Administrator).", "Call `GET https://graph.microsoft.com/v1.0/copilot/reports/getMicrosoft365CopilotUsageUserDetail(period='D28')` (also UserCountSummary and UserCountTrend). The default report version is v2, which accepts D7, D28, D90, D180 and ALL; D30 is only valid with `version='v1'`. v1.0 returns a CSV stream, beta returns JSON.", "Schedule with Azure Automation or a Logic App and store the results."], "v": "2026-11-07", "n": 2, "tg": ["Copilot", "Licensing", "PowerShell & Graph"], "c": "2026-10-12"}, {"id": "license-inventory-script", "category": "Licensing & reporting", "title": "List who has which license with Graph PowerShell", "problem": "You need a quick inventory of license assignments for cost review.", "steps": ["`Connect-MgGraph -Scopes 'User.Read.All','Organization.Read.All'`", "`$skus = Get-MgSubscribedSku | Select SkuId, SkuPartNumber, ConsumedUnits, @{n='Enabled';e={$_.PrepaidUnits.Enabled}}`", "`Get-MgUser -All -Property DisplayName,UserPrincipalName,AssignedLicenses | Select DisplayName,UserPrincipalName,@{n='Skus';e={($_.AssignedLicenses.SkuId | % { $id=$_; ($skus | ? SkuId -eq $id).SkuPartNumber }) -join ';'}} | Export-Csv licenses.csv -NoTypeInformation`"], "v": "2026-10-30", "n": 2, "tg": ["Licensing", "PowerShell & Graph"], "c": "2026-10-12"}, {"id": "copilot-chat-pay-as-you-go", "category": "Licensing & reporting", "title": "Understand Microsoft Copilot Chat vs Microsoft Copilot (licensed)", "problem": "Leadership is confused about what's free and what requires a license.", "steps": ["Naming: Microsoft 365 Copilot is now called Microsoft Copilot, and Microsoft 365 Copilot Chat is now Microsoft Copilot Chat.", "Microsoft Copilot Chat is included for users with an eligible Microsoft 365 subscription: web-grounded chat, file upload and agents, with enterprise data protection.", "Pay-as-you-go billing can be turned on for metered agents in Copilot Chat, SharePoint agents and the Copilot Retrieval API.", "Microsoft Copilot (add-on license) adds work grounding across Microsoft Graph and the full in-app experiences.", "Map scenarios to the right tier before buying."], "v": "2026-10-30", "n": 2, "tg": ["Copilot", "Licensing"], "c": "2026-10-12"}, {"id": "prompt-1", "category": "Admin prompt templates", "title": "Prompt: summarize a Conditional Access policy export", "problem": "You have a JSON export of CA policies and need a human-readable summary.", "steps": ["Open Microsoft Copilot Chat (formerly Microsoft 365 Copilot Chat) or your approved AI tool.", "Paste the JSON and use: 'You are a Microsoft Entra Conditional Access expert. Summarize each policy in this JSON as a table with columns: name, state, included users, excluded users, target resources, conditions, grant controls, session controls. Then list gaps (e.g., missing break-glass exclusions, policies stuck in report-only).'", "Review the output critically and verify facts against official documentation."], "v": "2026-10-30", "n": 1, "tg": ["Conditional Access", "Prompts"], "c": "2026-10-12"}, {"id": "prompt-2", "category": "Admin prompt templates", "title": "Prompt: write a Copilot rollout announcement", "problem": "You need a clear end-user announcement for Copilot.", "steps": ["Open Microsoft Copilot Chat (formerly Microsoft 365 Copilot Chat) or your approved AI tool.", "'Write a 200-word announcement for employees that Microsoft Copilot is being rolled out to [group] on [date]. Include: what it is, 3 concrete use cases for [department], where to get training, and a reminder that Copilot only shows content they already have access to.'", "Review the output critically and verify facts against official documentation."], "v": "2026-10-30", "n": 1, "tg": ["Copilot", "Prompts"], "c": "2026-10-12"}, {"id": "prompt-3", "category": "Admin prompt templates", "title": "Prompt: explain an Intune error to the help desk", "problem": "Help desk staff don't understand Intune error codes.", "steps": ["Open Microsoft Copilot Chat (formerly Microsoft 365 Copilot Chat) or your approved AI tool.", "'Explain this Intune error to a level-1 help desk agent: [error text]. Give likely causes, safe first steps, and when to escalate. Do not invent error codes; say if you are unsure.'", "Review the output critically and verify facts against official documentation."], "v": "2026-10-30", "n": 1, "tg": ["Intune", "Prompts"], "c": "2026-10-12"}, {"id": "prompt-4", "category": "Admin prompt templates", "title": "Prompt: draft a Copilot acceptable use policy", "problem": "You need a starting point for an AI acceptable use policy.", "steps": ["Open Microsoft Copilot Chat (formerly Microsoft 365 Copilot Chat) or your approved AI tool.", "'Draft an acceptable use policy for generative AI tools at [company]. Cover: approved tools, data that must not be entered, verifying outputs, sensitivity labels, reporting incidents, and consequences. Keep it under 1 page and in plain language.'", "Review the output critically and verify facts against official documentation."], "v": "2026-10-30", "n": 1, "tg": ["Copilot", "Prompts"], "c": "2026-10-12"}];